+
+    .card {
+      background: rgba(17, 26, 45, 0.92);
+      border: 1px solid rgba(124, 156, 255, 0.18);
+      border-radius: 20px;
+      padding: 28px;
+      box-shadow: var(--shadow);
+      backdrop-filter: blur(12px);
+    }
+
+    h1 {
+      margin: 0 0 10px;
+      font-size: 1.5rem;
+      line-height: 1.2;
+    }
+
+    .intro {
+      margin: 0 0 24px;
+      color: var(--muted);
+    }
+
+    form {
+      display: grid;
+      gap: 20px;
+    }
+
+    .form-field {
+      padding: 18px;
+      border: 1px solid var(--panel-border);
+      border-radius: 16px;
+      background: rgba(7, 12, 22, 0.46);
+    }
+
+    .checkbox-row {
+      display: flex;
+      gap: 12px;
+      align-items: flex-start;
+    }
+
+    input[type="checkbox"] {
+      width: 20px;
+      height: 20px;
+      margin: 2px 0 0;
+      border-radius: 5px;
+      border: 1px solid #7f8db0;
+      background: #0d1627;
+      accent-color: var(--accent);
+      flex: none;
+    }
+
+    input[type="checkbox"]:focus-visible,
+    button:focus-visible,
+    .skip-link:focus-visible {
+      outline: 3px solid var(--accent-strong);
+      outline-offset: 3px;
+    }
+
+    label {
+      display: block;
+      font-weight: 650;
+      color: var(--text);
+    }
+
+    .helper,
+    .error,
+    .status {
+      margin: 8px 0 0;
+      font-size: 0.95rem;
+    }
+
+    .helper {
+      color: var(--muted);
+    }
+
+    .error {
+      color: var(--danger);
+    }
+
+    .actions {
+      display: flex;
+      flex-wrap: wrap;
+      gap: 12px;
+      align-items: center;
+    }
+
+    button {
+      appearance: none;
+      border: 0;
+      border-radius: 999px;
+      padding: 12px 18px;
+      background: linear-gradient(180deg, #92a8ff 0%, #6f8dff 100%);
+      color: #08101d;
+      font: inherit;
+      font-weight: 700;
+      cursor: pointer;
+      box-shadow: 0 12px 28px rgba(111, 141, 255, 0.28);
+    }
+
+    .status {
+      color: #cbd6f5;
+      min-height: 1.5em;
+    }
+
+    @media (max-width: 420px) {
+      body {
+        padding: 16px;
+      }
+
+      .card {
+        padding: 22px;
+      }
+
+      .form-field {
+        padding: 14px;
+      }
+    }
+  </style>
+</head>
+<body>
+  <a class="skip-link" href="#main-content">Skip to main content</a>
+  <main id="main-content"></main>
+
+  <script>
+    function CheckboxField() {
+      return `
+        <div class="form-field">
+          <div class="checkbox-row">
+            <input
+              id="terms"
+              name="terms"
+              type="checkbox"
+              required
+              aria-describedby="terms-help terms-error"
+            />
+            <div>
+              <label for="terms">I agree to the Terms of Use <span aria-hidden="true">*</span></label>
+              <p id="terms-help" class="helper">Required to continue.</p>
+              <p id="terms-error" class="error" role="alert" hidden></p>
+            </div>
+          </div>
+        </div>
+      `;
+    }
+
+    function App() {
+      return `
+        <article class="card" aria-labelledby="title">
+          <h1 id="title">Consent form</h1>
+          <p class="intro">Please confirm that you agree to the terms before continuing.</p>
+          <form id="consent-form" novalidate>
+            ${CheckboxField()}
+            <div class="actions">
+              <button type="submit">Agree and continue</button>
+            </div>
+            <p id="form-status" class="status" role="status" aria-live="polite"></p>
+          </form>
+        </article>
+      `;
+    }
+
+    const main = document.getElementById('main-content');
+    main.innerHTML = App();
+
+    const form = document.getElementById('consent-form');
+    const checkbox = document.getElementById('terms');
+    const error = document.getElementById('terms-error');
+    const status = document.getElementById('form-status');
+
+    function clearError() {
+      checkbox.removeAttribute('aria-invalid');
+      error.hidden = true;
+      error.textContent = '';
+    }
+
+    checkbox.addEventListener('change', () => {
+      if (checkbox.checked) {
+        clearError();
+      }
+    });
+
+    form.addEventListener('submit', (event) => {
+      event.preventDefault();
+
+      if (!checkbox.checked) {
+        checkbox.setAttribute('aria-invalid', 'true');
+        error.textContent = 'Error: You must agree to the terms to continue.';
+        error.hidden = false;
+        status.textContent = '';
+        checkbox.focus();
+        return;
+      }
+
+      clearError();
+      status.textContent = 'Consent confirmed.';
+    });
+  </script>
+</body>
+</html>
*** End Patch
